    const d = Number(m[1] || m[5]);
    const mo = Number(m[3] || m[6]);
    const yRaw = m[4] || m[7];
    const y = yRaw ? Number(yRaw) : null;
    const iso = isValidYmd(y ? (y < 100 ? 2000 + y : y) : 2000, mo, d) ? resolveDayMonth(d, mo, y, today) : null;
    push(m, { iso, ambiguous: !iso, kind: 'explicit' });
  });
