  let text = normalizeWhitespace(body);
  const cut = (re) => {
    const m = re.exec(text);
    if (m && m.index > 0) text = text.slice(0, m.index);
  };
  REPLY_MARKERS.forEach(cut);
  text = text.split('\n').filter((line) => !/^\s*>/.test(line)).join('\n');
  SIGNATURE_MARKERS.forEach(cut);
