  const signOff = SIGN_OFF.exec(text);
  if (signOff && signOff.index > 0) {
    const tail = text.slice(signOff.index).split('\n');
    if (tail.length <= 8 && tail.every((line) => line.length <= 80)) text = text.slice(0, signOff.index);
