function findBookingReference(text) {
  const src = String(text || '');
  const keyword = /\b(?:PNR|booking(?:\s+(?:ref(?:erence)?|no\.?|number|code))?|ref(?:erence)?|record locator|locator)\s*[:#-]?\s*([A-Z0-9]{6})\b/i.exec(src);
